import{_ as a,o as i,c as t,a3 as n}from"./chunks/framework.qCVWde4n.js";const c=JSON.parse('{"title":"上传你的 Mod（作者）","description":"","frontmatter":{},"headers":[],"relativePath":"repo/publish.md","filePath":"repo/publish.md","lastUpdated":1791133906000}'),l={name:"repo/publish.md"};function o(e,s,r,d,h,p){return i(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="上传你的-mod-作者" tabindex="-1">上传你的 Mod（作者） <a class="header-anchor" href="#上传你的-mod-作者" aria-label="Permalink to &quot;上传你的 Mod（作者）&quot;">​</a></h1><p>做好一个 Mod，想让别人一键装上？直接<strong>在仓库网页上把它传上去</strong>，等管理员过审，就会出现在仓库列表里，所有人都能搜到、复制分享码、下载。</p><p>不用命令行、不用发给人代传，打开网页填个表就行。</p><h2 id="发布后的效果" tabindex="-1">发布后的效果 <a class="header-anchor" href="#发布后的效果" aria-label="Permalink to &quot;发布后的效果&quot;">​</a></h2><p>玩家打开仓库页，能对你的 Mod：</p><ul><li><strong>搜到</strong> —— 按名字 / 作者 / 说明 / 标签搜</li><li><strong>看详情</strong> —— 弹层显示完整说明 + <strong>这个 Mod 改了哪些参数</strong>（自动从你的 mod.json 读出来，还会标出每一项是调高还是调低）</li><li><strong>复制分享码</strong> —— 一点就复制，粘到任意聊天窗口就能发出去</li><li><strong>下载包体</strong> —— 想手动装的人用</li></ul><h2 id="三步上传" tabindex="-1">三步上传 <a class="header-anchor" href="#三步上传" aria-label="Permalink to &quot;三步上传&quot;">​</a></h2><h3 id="第一步-打开仓库页-滚到「把你的改装交上来」" tabindex="-1">第一步：打开仓库页，滚到「把你的改装交上来」 <a class="header-anchor" href="#第一步-打开仓库页-滚到「把你的改装交上来」" aria-label="Permalink to &quot;第一步：打开仓库页，滚到「把你的改装交上来」&quot;">​</a></h3><p>地址是仓库主页往下的<strong>上传区</strong>。也可以点右上角的「<strong>上传 Mod</strong>」按钮直达。</p><h3 id="第二步-填信息和文件" tabindex="-1">第二步：填信息和文件 <a class="header-anchor" href="#第二步-填信息和文件" aria-label="Permalink to &quot;第二步：填信息和文件&quot;">​</a></h3><ul><li><p><strong>作者</strong> —— 填你的名字 / 昵称。别人在仓库里看到的就是这个。</p></li><li><p><strong>联系方式（可选）</strong> —— 万一审核要问你，方便联系。</p></li><li><p><strong>mod.json 内容</strong> —— 两种方式，任选：</p><table tabindex="0"><thead><tr><th>方式</th><th>怎么做</th></tr></thead><tbody><tr><td>拖文件</td><td>把你的 <code>mod.json</code> <strong>拖进虚线框</strong>，或点框选文件</td></tr><tr><td>贴文本</td><td>直接把 JSON 文本<strong>粘到下方文本框</strong></td></tr></tbody></table><p>两种都行；拖了文件后再手改文本会以文本为准。</p></li></ul><h3 id="第三步-点「提交审核」" tabindex="-1">第三步：点「提交审核」 <a class="header-anchor" href="#第三步-点「提交审核」" aria-label="Permalink to &quot;第三步：点「提交审核」&quot;">​</a></h3><p>提交后会提示「已提交，等待管理员审核」。<strong>这时候还没上架</strong> —— 要等管理员在后台点「通过」才会出现在仓库里。</p><h2 id="什么样的-mod-json-能过审" tabindex="-1">什么样的 mod.json 能过审 <a class="header-anchor" href="#什么样的-mod-json-能过审" aria-label="Permalink to &quot;什么样的 mod.json 能过审&quot;">​</a></h2><p>只要能<strong>正常在游戏内加载</strong>，基本上就能过。具体：</p><ul><li><strong><code>modName</code> 必填</strong>，没有名字的包会被直接拒。</li><li>建议把 <code>author</code>、<code>version</code>、<code>description</code> 都写上，仓库卡片显示得更好看。</li><li>参数值别超出<a href="/AtlanticFleetSite/docs/dev/param-keys">参数键全表</a>里的硬边界——超了会被游戏静默钳制，实际效果和你写的不一样（这是最难查的坑）。</li><li>大小上限 <strong>32 MB</strong>（正常 mod.json 也就几 KB）。</li></ul><p>一个最小的例子：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;modName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;我的超级 Mod&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;author&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;uruban&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;一句话说明你这个 Mod 干了什么&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;数值&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;休闲&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;combat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;gun&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;damageMul&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="审核会看什么" tabindex="-1">审核会看什么 <a class="header-anchor" href="#审核会看什么" aria-label="Permalink to &quot;审核会看什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>会看</th><th>不会看</th></tr></thead><tbody><tr><td>mod.json 格式是否合法、能不能加载</td><td>你的 Mod 好不好玩</td></tr><tr><td>有没有重名（和已有的撞名会被退回）</td><td>你的 Mod 是不是原创</td></tr><tr><td>内容有没有明显问题</td><td>你的 Mod 强度是否平衡</td></tr></tbody></table><p>过审 → 自动上架，生成分享码，所有人可下载。 被驳回 → 会附一句原因，改完可以重新传。</p><h2 id="上传后想改" tabindex="-1">上传后想改？ <a class="header-anchor" href="#上传后想改" aria-label="Permalink to &quot;上传后想改？&quot;">​</a></h2><p>现在还没有「在线改」的功能，<strong>重新传一份新的就行</strong>：</p><ol><li>在 <code>mod.json</code> 里把 <code>version</code> 改高（比如 <code>1.0</code> → <code>1.1</code>）；</li><li>再走一遍上传流程。</li></ol><div class="tip custom-block"><p class="custom-block-title">重名规则</p><p>同名（<code>modName</code> 相同）的包如果是<strong>待审 / 已上架</strong>状态，会被拒。所以：</p><ul><li>想更新自己的 Mod → 先联系管理员把旧的下架，或换个名字传；</li><li>纯粹想测试 → 名字里加个「测试」字样，避免和正式版撞。</li></ul></div><h2 id="上传前自检清单" tabindex="-1">上传前自检清单 <a class="header-anchor" href="#上传前自检清单" aria-label="Permalink to &quot;上传前自检清单&quot;">​</a></h2><ul><li>[ ] <code>mod.json</code> 有 <code>modName</code></li><li>[ ] 参数值没超硬边界（对照 <a href="/AtlanticFleetSite/docs/dev/param-keys">参数键全表</a>）</li><li>[ ] 舰级 / 编队名不太容易和别人撞</li><li>[ ] 文件大小 &lt; 32 MB</li><li>[ ] 提交后在仓库里刷新，能看到自己的 Mod（过审后）</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想自己搭一个同样的仓库？→ <a href="/AtlanticFleetSite/docs/repo/admin">自建仓库（站长）</a></li><li>Mod 怎么写 → <a href="/AtlanticFleetSite/docs/dev/mod-json">mod.json 完整规范</a></li><li>想用自制模型 → <a href="/AtlanticFleetSite/docs/dev/assetbundle">制作 AssetBundle 模型</a></li></ul>`,29)])])}const u=a(l,[["render",o]]);export{c as __pageData,u as default};
